<?php require_once __DIR__ . '/workflow_nav.php'; ?><?php require_once __DIR__ . '/workflow_nav.php'; ?></main></div><script>(function(){var sb=document.querySelector('.sidebar');var h=document.getElementById('sidebarHandle');if(!sb||!h)return;var w=localStorage.getItem('erp_sidebar_w');if(w){sb.style.width=w+'px';}var d=false;h.addEventListener('mousedown',function(e){d=true;e.preventDefault();});document.addEventListener('mousemove',function(e){if(!d)return;var nw=Math.max(130,Math.min(420,e.clientX));sb.style.width=nw+'px';});document.addEventListener('mouseup',function(){if(d){localStorage.setItem('erp_sidebar_w',parseInt(sb.style.width,10));d=false;}});})();</script></body></html>
